import { chromium } from '@playwright/test'
const b=await chromium.launch({executablePath:'C:/Users/Administrator/AppData/Local/ms-playwright/chromium-1243/chrome-win64/chrome.exe'})
const pg=await b.newPage({viewport:{width:390,height:844}})
const fontReqs=[]; const figmaReqs=[]
pg.on('request', r=>{ const u=r.url(); if(/\.woff2?(\?|$)/.test(u)) fontReqs.push(u); if(u.includes('figma.com')) figmaReqs.push(u) })
await pg.goto('http://127.0.0.1:8099/#/pages/inspection/index?kind=pre',{waitUntil:'domcontentloaded',timeout:25000}).catch(e=>console.log('goto',e.message))
await pg.waitForTimeout(3000)
const r=await pg.evaluate(()=>{
  const sz=s=>{const el=document.querySelector(s);return el?getComputedStyle(el).fontSize:null}
  const fam=s=>{const el=document.querySelector(s);return el?getComputedStyle(el).fontFamily:null}
  return {counterVal:sz('.counter-val'), fieldBlockLabel:sz('.field-block-label'), bodyFont:fam('body')||fam('page'), headers:[...document.querySelectorAll('uni-page-head,.app-header')].map(e=>(e.className||'native'))}
})
console.log('font requests:', JSON.stringify(fontReqs))
console.log('figma requests:', JSON.stringify(figmaReqs))
console.log('compute:', JSON.stringify(r,null,2))
await pg.screenshot({path:'D:/repository/_sysfont.png'})
await b.close()

